var iconPath = "Assets/Resources/Skills/Data/PhotonRadiance/Icon.png";
UnityEditor.AssetDatabase.Refresh();

var importer = UnityEditor.AssetImporter.GetAtPath(iconPath) as UnityEditor.TextureImporter;
if (importer == null)
{
    UnityEngine.Debug.LogError($"TextureImporter not found for: {iconPath}");
    return;
}

// 设置导入参数
importer.textureType = UnityEditor.TextureImporterType.Sprite;
importer.spritePixelsPerUnit = 100;
importer.filterMode = UnityEngine.FilterMode.Point;
importer.mipmapEnabled = false;
importer.textureCompression = UnityEditor.TextureImporterCompression.Uncompressed;
importer.crunchedCompression = false;
importer.spriteImportMode = UnityEditor.SpriteImportMode.Single;
importer.alphaIsTransparency = true;

// 确保硬件纹理可读写（编辑器内用）
importer.isReadable = true;

importer.SaveAndReimport();

// 重新加载 Sprite
var sprite = UnityEditor.AssetDatabase.LoadAssetAtPath<UnityEngine.Sprite>(iconPath);
if (sprite != null)
{
    UnityEngine.Debug.Log($"Sprite loaded: {sprite.name}, rect={sprite.rect}, PPU={sprite.pixelsPerUnit}, border={sprite.border}");
    // 检查 border
    if (sprite.border.x > 0 || sprite.border.y > 0 || sprite.border.z > 0 || sprite.border.w > 0)
        UnityEngine.Debug.Log($"WARNING: Sprite has border: {sprite.border}");
    else
        UnityEngine.Debug.Log("OK: No border on sprite");
}
else
    UnityEngine.Debug.LogError("Failed to load sprite after reimport!");

// 验证 PhotonRadiance.asset 的 icon 引用
var assetPath = "Assets/Resources/Skills/Data/PhotonRadiance/PhotonRadiance.asset";
var skillData = UnityEditor.AssetDatabase.LoadAssetAtPath<UnityEngine.ScriptableObject>(assetPath);
if (skillData == null)
{
    UnityEngine.Debug.LogError($"PhotonRadiance.asset not found at: {assetPath}");
    return;
}

// 用 SerializedObject 检查 icon 字段
var so = new UnityEditor.SerializedObject(skillData);
var iconProp = so.FindProperty("icon");
if (iconProp != null)
{
    if (iconProp.objectReferenceValue != null)
        UnityEngine.Debug.Log($"icon field: {iconProp.objectReferenceValue.name} (type={iconProp.objectReferenceValue.GetType().Name})");
    else
        UnityEngine.Debug.LogWarning("icon field is NULL — reference broken!");
}
else
{
    // 尝试常用别名: _icon / m_Icon
    var iconProp2 = so.FindProperty("_icon");
    if (iconProp2 != null && iconProp2.objectReferenceValue != null)
        UnityEngine.Debug.Log($"icon field (_icon): {iconProp2.objectReferenceValue.name}");
    else
    {
        var iconProp3 = so.FindProperty("m_Icon");
        if (iconProp3 != null && iconProp3.objectReferenceValue != null)
            UnityEngine.Debug.Log($"icon field (m_Icon): {iconProp3.objectReferenceValue.name}");
        else
            UnityEngine.Debug.Log("icon field not found. Checking all properties...");
    }
}

// 查找 SkillData 类型
var sdType = skillData.GetType();
UnityEngine.Debug.Log($"SkillData type: {sdType.FullName}");
// 列出所有字段
foreach (var field in sdType.GetFields(System.Reflection.BindingFlags.Public | System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Instance))
{
    if (field.Name.ToLower().Contains("icon"))
    {
        var val = field.GetValue(skillData);
        UnityEngine.Debug.Log($"Field: {field.Name} = {(val != null ? val.ToString() : "NULL")}");
    }
}

