UnityEngine.Debug.Log($"  mipmapEnabled: {importer.mipmapEnabled}");

// PPU check: unity shows 12.5 but should be 100
if (System.Math.Abs(importer.spritePixelsPerUnit - 100f) > 0.01f)
{
    UnityEngine.Debug.Log($"WARNING: spritePixelsPerUnit={importer.spritePixelsPerUnit}, fixing to 100...");
    importer.spritePixelsPerUnit = 100;
    importer.SaveAndReimport();

    // Reload
    var sprite2 = UnityEditor.AssetDatabase.LoadAssetAtPath<UnityEngine.Sprite>(iconPath);
    UnityEngine.Debug.Log($"After fix: PPU={sprite2.pixelsPerUnit}, size={sprite2.rect.size}");
}
else
{
    UnityEngine.Debug.Log("PPU already = 100 ✓");
}

// Final image info
var sprite = UnityEditor.AssetDatabase.LoadAssetAtPath<UnityEngine.Sprite>(iconPath);
var tex = UnityEditor.AssetDatabase.LoadAssetAtPath<UnityEngine.Texture2D>(iconPath);
UnityEngine.Debug.Log($"=== Final State ===");
