UnityEngine.Debug.Log($"  Sprite border: {sprite.border}");
UnityEngine.Debug.Log($"  Filter mode: {tex.filterMode}");
UnityEngine.Debug.Log($"  Mipmap count: {tex.mipmapCount}");

// Confirm PhotonRadiance.asset icon GUID
var assetPath = "Assets/Resources/Skills/Data/PhotonRadiance/PhotonRadiance.asset";
var skillData = UnityEditor.AssetDatabase.LoadAssetAtPath<UnityEngine.ScriptableObject>(assetPath);
var so = new UnityEditor.SerializedObject(skillData);
var iconProp = so.FindProperty("icon");
if (iconProp != null && iconProp.objectReferenceValue != null)
{
    var iconGuid = UnityEditor.AssetDatabase.AssetPathToGUID(iconPath);
    var refGuid = UnityEditor.AssetDatabase.AssetPathToGUID(UnityEditor.AssetDatabase.GetAssetPath(iconProp.objectReferenceValue));
    UnityEngine.Debug.Log($"  Icon GUID: {iconGuid}");
    UnityEngine.Debug.Log($"  Reference GUID: {refGuid}");
    UnityEngine.Debug.Log($"  GUID match: {(iconGuid == refGuid ? "YES ✓" : "NO ✗")}");
}

